    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free(x):
            res = 1
            i = 2
            while i * i <= x:
                cnt = 0
                while x % i == 0:
                    x //= i
                    cnt += 1
                if cnt % 2 == 1:
                    res *= i
                i += 1
            if x > 1:
                res *= x
            return res

