            if n == 0:
                return 0
            res = 1
            # Factor out 2
            count = 0
            while n % 2 == 0:
                count += 1
                n = n // 2
            if count % 2 == 1:
                res *= 2
            # Factor odd numbers
            i = 3
            while i * i <= n:
                count = 0
                while n % i == 0:
                    count += 1
                    n = n // i
                if count % 2 == 1:
                    res *= i
                i += 2
            if n > 1:
                res *= n
            return res

        groups = defaultdict(int)
        for idx, num in enumerate(nums):
            i = idx + 1  # 1-based index
            sf = square_free_part(i)
            groups[sf] += num

        return max(groups.values())
