class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        freq = Counter(nums)
        max_len = 1  # The minimum possible length is 1

        for x in freq:
            if x == 1:
                # Special case for 1
                m = (freq[x] - 1) // 2
                current_len = 2 * m + 1
                if current_len > max_len:
                    max_len = current_len
            else:
                current_val = x
                count = 0
                while True:
                    if freq.get(current_val, 0) < 2:
                        break
                    next_val = current_val * current_val
                    if next_val in freq:
                        current_val = next_val
                        count += 1
                    else:
                        break
                current_len = 2 * count + 1
                if current_len > max_len:
                    max_len = current_len

        return max_len

